413	  /**
414	   * Get the active span from the handler context,
415	   * falling back to the active thread span if there
416	   * is nothing in the context.
417	   * Provided the span is a wrapped span, the
418	   * @param request request
419	   * @param <T> type of request.
420	   * @return the callbacks
421	   */
422	  private <T extends HandlerContextAware> AWSAuditEventCallbacks
423	      extractAndActivateSpanFromRequest(final T request) {
424	    AWSAuditEventCallbacks span;
425	    span = retrieveAttachedSpan(request);
426	    if (span == null) {
427	      // no span is attached. Not unusual for the copy operations,
428	      // or for calls to GetBucketLocation made by the AWS client
429	      LOG.debug("No audit span attached to request {}",
430	          request);
431	      // fall back to the active thread span.
432	      // this will be the unbonded span if the thread is unbonded.
433	      span = getActiveAuditSpan();
434	    } else {
435	      if (span instanceof WrappingAuditSpan) {
436	        switchToActiveSpan((WrappingAuditSpan) span);
437	      } else {
438	        // warn/log and continue without switching.
439	        WARN_OF_SPAN_TYPE.warn(NOT_A_WRAPPED_SPAN + ": {}", span);
440	        LOG.debug(NOT_A_WRAPPED_SPAN + ": {}", span);
441	      }
442	    }
443	    return span;
444	  }
