582	  /**
583	   * Wraps the plugged in spans with management of the active thread
584	   * span, including switching to the unbounded span when a valid
585	   * span is deactivated.
586	   * Package-private for testing.
587	   */
588	  private final class WrappingAuditSpan extends AbstractAuditSpanImpl {
589	
590	    /**
591	     * Inner span.
592	     */
593	    private final AuditSpanS3A span;
594	
595	    /**
596	     * Is this span considered valid?
597	     */
598	    private final boolean isValid;
599	
600	    /**
601	     * Create, wrapped.
602	     * The spanID, name, timestamp etc copied from the span being wrapped.
603	     * Why not the isValid state? We want to set our unbonded span without
604	     * relying on the auditor doing the right thing.
605	     * @param span inner span.
606	     * @param isValid is the span valid
607	     */
608	    private WrappingAuditSpan(
609	        final AuditSpanS3A span, final boolean isValid) {
610	      super(span.getSpanId(), span.getTimestamp(), span.getOperationName());
611	      this.span = requireNonNull(span);
612	      this.isValid = isValid;
613	    }
614	
615	    /**
616	     * Is the span active?
617	     * @return true if this span is the active one for the current thread.
618	     */
619	    private boolean isActive() {
620	      return this == getActiveAuditSpan();
621	    }
622	
623	    /**
624	     * Makes this the thread's active span and activate.
625	     * If the span was already active: no-op.
626	     */
627	    @Override
628	    public AuditSpanS3A activate() {
629	      if (!isActive()) {
630	        switchToActiveSpan(this);
631	        span.activate();
632	      }
633	      return this;
634	    }
635	
636	    /**
637	     * Switch to the unbounded span and then deactivate this span.
638	     * No-op for invalid spans,
639	     * so as to prevent the unbounded span from being closed
640	     * and everything getting very confused.
641	     */
642	    @Override
643	    public void deactivate() {
644	      // no-op for invalid spans,
645	      // so as to prevent the unbounded span from being closed
646	      // and everything getting very confused.
647	      if (!isValid || !isActive()) {
648	        return;
649	      }
650	      // deactivate the span
651	      span.deactivate();
652	      // and go to the unbounded one.
653	      switchToActiveSpan(getUnbondedSpan());
654	    }
655	
656	    /**
657	     * Forward to the wrapped span.
658	     * {@inheritDoc}
659	     */
660	    @Override
661	    public <T extends AmazonWebServiceRequest> T requestCreated(
662	        final T request) {
663	      return span.requestCreated(request);
664	    }
665	
666	    /**
667	     * This span is valid if the span isn't closed and the inner
668	     * span is valid.
669	     * @return true if the span is considered valid.
670	     */
671	    @Override
672	    public boolean isValidSpan() {
673	      return isValid && span.isValidSpan();
674	    }
675	
676	    /**
677	     * Forward to the inner span.
678	     * {@inheritDoc}
679	     */
680	    @Override
681	    public void set(final String key, final String value) {
682	      span.set(key, value);
683	    }
684	
685	    /**
686	     * Forward to the inner span.
687	     * @param request request
688	     * @param <T> type of request
689	     * @return an updated request.
690	     */
691	    @Override
692	    public <T extends AmazonWebServiceRequest> T beforeExecution(
693	        final T request) {
694	      return span.beforeExecution(request);
695	    }
696	
697	    /**
698	     * Forward to the inner span.
699	     * @param request request
700	     * @param response response.
701	     */
702	    @Override
703	    public void afterResponse(final Request<?> request,
704	        final Response<?> response) {
705	      span.afterResponse(request, response);
706	    }
707	
708	    /**
709	     * Forward to the inner span.
710	     * @param request request
711	     * @param response response.
712	     * @param exception exception raised.
713	     */
714	    @Override
715	    public void afterError(final Request<?> request,
716	        final Response<?> response,
717	        final Exception exception) {
718	      span.afterError(request, response, exception);
719	    }
720	
721	    /**
722	     * Forward to the inner span.
723	     * @param request request
724	     * @return request to marshall
725	     */
726	    @Override
727	    public AmazonWebServiceRequest beforeMarshalling(
728	        final AmazonWebServiceRequest request) {
729	      return span.beforeMarshalling(request);
730	    }
